import json
from itertools import permutations

def solve_puzzle():
    houses = [1, 2, 3, 4, 5]

    names = ['Peter', 'Alice', 'Bob', 'Eric', 'Arnold']
    heights = ['very tall', 'average', 'tall', 'very short', 'short']

    # Pre-fix constraints inferred directly:
    # - The person with average height is in the 5th house.
    # - Alice is directly left of the average height person -> Alice is in the 4th house.
    fixed_average_pos = 5
    fixed_alice_pos = 4

    solutions = []

    # Iterate over permutations of names with Alice fixed at position 4 (index 3)
    for name_perm in permutations(names):
        if name_perm[fixed_alice_pos - 1] != 'Alice':
            continue

        # Build index map for names (1-based positions)
        name_pos = {name_perm[i]: i + 1 for i in range(5)}

        # Constraint 2: Peter is directly left of Bob.
        if not (name_pos['Peter'] + 1 == name_pos['Bob']):
            continue

        # Constraint 3: Eric is somewhere to the left of Peter.
        if not (name_pos['Eric'] < name_pos['Peter']):
            continue

        # Now iterate over height permutations
        for height_perm in permutations(heights):
            height_pos = {height_perm[i]: i + 1 for i in range(5)}

            # Constraint 1: The person who is short is in the second house.
            if height_pos['short'] != 2:
                continue

            # Constraint 7: The person who has an average height is in the fifth house.
            if height_pos['average'] != fixed_average_pos:
                continue

            # Constraint 5: Alice is directly left of the person who has an average height.
            if not (name_pos['Alice'] + 1 == height_pos['average']):
                continue

            # Constraint 4: The person who is very tall is directly left of Peter.
            if not (height_pos['very tall'] + 1 == name_pos['Peter']):
                continue

            # Constraint 6: The person who is short and the person who is very short are next to each other.
            if abs(height_pos['short'] - height_pos['very short']) != 1:
                continue

            # If all constraints satisfied, record solution
            solution_rows = []
            for h in houses:
                solution_rows.append([
                    str(h),
                    name_perm[h - 1],
                    height_perm[h - 1]
                ])

            solutions.append({
                "solution": {
                    "header": ["House", "Name", "Height"],
                    "rows": solution_rows
                }
            })

    # Assuming unique solution; return the first one if multiple (should be unique)
    return solutions[0] if solutions else {"solution": {"header": ["House", "Name", "Height"], "rows": []}}

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
